// Generated by /ship coverage audit (Claude) — 2026-10-16
// Value: protects=/sessions bounds the query by real from/to dates only, hands that range, the Vietnam clock, the queue facts read at the RPC maximum (500) with their status (ok / failed / partial at a full page) and each permission flag to the list, and gives the queue panel the same today for its filter link;
// fails_when=an undated Chờ khóa / Chưa điểm danh URL is read unbounded (newest-300 spent on future sessions), an impossible or repeated date reaches the query, loadedRange drifts from it, today uses the UTC date, a failed queue still feeds readiness or is reported ok, a full page is reported complete, the queue cap drifts from 500, or a flag is dropped;
// why_new=step 14a moves this wiring into the route; list tests pass these props directly; seam=none; no_claim=not RLS, the RPC or real queries; frozen timers make every new Date() equal, so "one instant" is not proven
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import SessionsRoute from "@/app/(app)/sessions/page";
import type { UnlockedSessionQueue } from "@/features/sessions/components/unlocked-session-queue";
import type { SessionListPage } from "@/features/sessions/session-list-page";

const dependencies = vi.hoisted(() => ({
  getCachedDatabasePermissions: vi.fn(),
  getSessionDirectory: vi.fn(),
  getUnlockedSessionQueueResult: vi.fn(),
  SessionListPage: vi.fn(() => null),
  UnlockedSessionQueue: vi.fn(() => null),
}));

vi.mock("next/navigation", () => ({
  redirect: vi.fn((href: string) => {
    throw new Error(`NEXT_REDIRECT ${href}`);
  }),
}));
vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/sessions/data", () => ({ getSessionDirectory: dependencies.getSessionDirectory }));
vi.mock("@/features/sessions/unlocked-sessions-data", () => ({
  getUnlockedSessionQueueResult: dependencies.getUnlockedSessionQueueResult,
}));
vi.mock("@/features/sessions/session-list-page", () => ({ SessionListPage: dependencies.SessionListPage }));
vi.mock("@/features/sessions/components/unlocked-session-queue", () => ({
  UnlockedSessionQueue: dependencies.UnlockedSessionQueue,
}));

const queueItem = {
  attendanceCount: 17,
  autoLockOn: null,
  classCode: "7B",
  classId: "class-7b",
  className: "Toán 7B",
  completedAt: "2026-10-15T03:00:00Z",
  completedByName: "Cô Lan",
  daysSinceCompleted: 1,
  endTime: "10:00:00",
  id: "s-ready",
  missingAttendanceCount: 0,
  rosterCount: 15,
  sessionDate: "2026-10-15",
  sessionKind: "regular",
  startTime: "08:00:00",
};

type ListElement = ReactElement<ComponentProps<typeof SessionListPage>>;

async function renderRoute(
  searchParams: Record<string, string | string[] | undefined>,
  permissions: string[],
  queueResult: unknown = { data: { autoLockAfterDays: 3, items: [queueItem] }, ok: true },
) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getSessionDirectory.mockResolvedValue({ ok: true, sessions: [] });
  dependencies.getUnlockedSessionQueueResult.mockResolvedValue(queueResult);
  const element = (await SessionsRoute({ searchParams: Promise.resolve(searchParams) })) as ReactElement<{ children: ListElement }>;
  return element.props.children;
}

afterEach(() => {
  vi.clearAllMocks();
  vi.useRealTimers();
});

describe("Sessions route (step 14a wiring)", () => {
  it("bounds the directory query by real calendar dates only and reports that range to the list", async () => {
    const list = await renderRoute({ from: "2026-10-12", status: "completed", to: "2026-10-18" }, ["sessions.view"]);
    expect(dependencies.getSessionDirectory).toHaveBeenLastCalledWith({
      dateFrom: "2026-10-12",
      dateTo: "2026-10-18",
      includeAttendanceCounts: false,
      includeResultCounts: false,
    });
    expect(list.type).toBe(dependencies.SessionListPage);
    expect(list.props.loadedRange).toEqual({ dateFrom: "2026-10-12", dateTo: "2026-10-18" });

    // An impossible date and a repeated param never bound the query: the unbounded newest window loads.
    const fallback = await renderRoute({ from: "2026-02-30", to: ["2026-10-01", "2026-10-02"] }, ["sessions.view"]);
    expect(dependencies.getSessionDirectory).toHaveBeenLastCalledWith(expect.objectContaining({ dateFrom: null, dateTo: null }));
    expect(fallback.props.loadedRange).toEqual({ dateFrom: null, dateTo: null });
  });

  it("maps each permission to its own prop and count read, and asks the queue for its 500-row maximum", async () => {
    const full = await renderRoute({}, ["sessions.view", "attendance.view", "results.view", "sessions.lock", "attendance.mark", "classes.view", "sessions.manage"]);
    expect(dependencies.getSessionDirectory).toHaveBeenLastCalledWith(expect.objectContaining({ includeAttendanceCounts: true, includeResultCounts: true }));
    expect(dependencies.getUnlockedSessionQueueResult).toHaveBeenLastCalledWith(500);
    expect(full.props).toMatchObject({
      canLock: true,
      canManageSessions: true,
      canMarkAttendance: true,
      canViewAttendance: true,
      canViewClasses: true,
      canViewResults: true,
    });
    const panel = full.props.queuePanel as ReactElement<ComponentProps<typeof UnlockedSessionQueue>>;
    expect(panel.type).toBe(dependencies.UnlockedSessionQueue);
    expect(panel.props).toMatchObject({ canLock: true, canMarkAttendance: true, limit: 500, today: full.props.today });

    // A TA-like set: marking without locking, results without attendance, no class pages.
    const ta = await renderRoute({}, ["sessions.view", "results.view", "attendance.mark"]);
    expect(dependencies.getSessionDirectory).toHaveBeenLastCalledWith(expect.objectContaining({ includeAttendanceCounts: false, includeResultCounts: true }));
    expect(ta.props).toMatchObject({
      canLock: false,
      canManageSessions: false,
      canMarkAttendance: true,
      canViewAttendance: false,
      canViewClasses: false,
      canViewResults: true,
    });
    expect((ta.props.queuePanel as ReactElement<ComponentProps<typeof UnlockedSessionQueue>>).props).toMatchObject({ canLock: false, canMarkAttendance: true });
  });

  it("passes only the queue facts the list needs, and none when the queue failed (readiness unknown, never ready)", async () => {
    const list = await renderRoute({}, ["sessions.view"]);
    expect(list.props.queueItems).toEqual([{ id: "s-ready", missingAttendanceCount: 0, rosterCount: 15 }]);
    expect(list.props.queueStatus).toBe("ok");

    const failed = await renderRoute({}, ["sessions.view"], { error: "boom", ok: false });
    expect(failed.type).toBe(dependencies.SessionListPage);
    expect(failed.props.queueItems).toBeUndefined();
    expect(failed.props.queuePanel).toBeNull();
    expect(failed.props.queueStatus).toBe("failed");

    // A full page may have cut the most recently completed sessions.
    const items = (count: number) => Array.from({ length: count }, (_, index) => ({ ...queueItem, id: `s-${index}` }));
    const full = await renderRoute({}, ["sessions.view"], { data: { autoLockAfterDays: 3, items: items(500) }, ok: true });
    expect(full.props.queueStatus).toBe("partial");
    expect(full.props.queueItems).toHaveLength(500);
    const below = await renderRoute({}, ["sessions.view"], { data: { autoLockAfterDays: 3, items: items(499) }, ok: true });
    expect(below.props.queueStatus).toBe("ok");
  });

  it("gives the list the Vietnam business date and wall-clock time of one instant", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    // 17:30 UTC on 15/10 is 00:30 on 16/10 in Vietnam: the UTC date would be a day behind.
    vi.setSystemTime(new Date("2026-10-15T17:30:00Z"));
    const list = await renderRoute({}, ["sessions.view"]);
    expect(list.props.today).toBe("2026-10-16");
    expect(list.props.nowTime).toBe("00:30:00");
  });

  it("bounds the undated Chờ khóa and Chưa điểm danh URLs at today before reading (the stored digest link)", async () => {
    vi.useFakeTimers({ now: new Date("2026-10-16T05:00:00Z"), toFake: ["Date"] });

    await expect(SessionsRoute({ searchParams: Promise.resolve({ lock: "unlocked", status: "completed" }) })).rejects.toThrow(
      "NEXT_REDIRECT /sessions?lock=unlocked&status=completed&to=2026-10-16",
    );
    await expect(SessionsRoute({ searchParams: Promise.resolve({ attendance: "missing", kind: "makeup" }) })).rejects.toThrow(
      "NEXT_REDIRECT /sessions?attendance=missing&kind=makeup&to=2026-10-16",
    );
    // An impossible date counts as no date, so it is replaced by the bound.
    await expect(SessionsRoute({ searchParams: Promise.resolve({ lock: "unlocked", status: "completed", to: "2026-02-30" }) })).rejects.toThrow(
      "NEXT_REDIRECT /sessions?lock=unlocked&status=completed&to=2026-10-16",
    );
    expect(dependencies.getSessionDirectory).not.toHaveBeenCalled();

    // Already bounded, or not one of the two sets: read as asked.
    await renderRoute({ lock: "unlocked", status: "completed", to: "2026-10-16" }, ["sessions.view"]);
    await renderRoute({ status: "completed" }, ["sessions.view"]);
    await renderRoute({ attendance: "missing", from: "2026-10-12" }, ["sessions.view"]);
    expect(dependencies.getSessionDirectory).toHaveBeenCalledTimes(3);
  });
});
